import { GENERATED_RECIPE_SKILLS, type GeneratedRecipeSkill } from "./recipeSkills.generated.ts";

// The skill levels where each recipe changes color in the profession window,
// from WoW: Forever's game data (recipeSkills.generated.ts, regenerated by
// apps/web/scripts/gen-recipe-skills.mjs; docs/game-data.md). Keyed by
// Blizzard's recipe id (recipes.recipeId).
//
// The game's rule: orange (always a skill-up) below yellow, yellow from
// `yellow`, green from halfway to grey, grey (no skill-ups) from `grey`.
// Where orange starts, the skill needed to learn the recipe, isn't in the
// game's data: trainers keep it on the server.

export type RecipeColor = "orange" | "yellow" | "green" | "grey";
export type RecipeSkill = GeneratedRecipeSkill & { profession: string; green: number };

const BY_ID = new Map<number, RecipeSkill>();
for (const [profession, recipes] of Object.entries(GENERATED_RECIPE_SKILLS)) {
	for (const r of recipes) BY_ID.set(r.id, { ...r, profession, green: Math.floor((r.yellow + r.grey) / 2) });
}

/** A recipe's levels, or undefined when the game's data doesn't have it (Guildie's own entries, say). */
export function recipeSkill(recipeId: number): RecipeSkill | undefined {
	return BY_ID.get(recipeId);
}

/** The recipe's color for someone at `skill`, as their profession window would show it. */
export function recipeColor(levels: Pick<RecipeSkill, "yellow" | "green" | "grey">, skill: number): RecipeColor {
	if (skill >= levels.grey) return "grey";
	if (skill >= levels.green) return "green";
	if (skill >= levels.yellow) return "yellow";
	return "orange";
}
